def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Uniform lines of the less-common color are structural dividers; change them to 2.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    candidates = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            candidates.append((r, 'row', row[0]))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((c, 'col', grid[0][c]))
    for k, axis, color in candidates:
        if color == bg:
            continue
        if axis == 'row': out[k] = [2] * w
        else:
            for r in range(h): out[r][k] = 2
    return out
